import json

import pytest

from open_weight_lingua import supersession_confirm as sc
from open_weight_lingua import tasks
from open_weight_lingua.splits import SPLIT_ORDER, build_plan


def _tiny_plan():
    from test_pilot_stages import TINY_COUNTS

    return build_plan(TINY_COUNTS)


@pytest.fixture
def test_split(monkeypatch):
    """Test-only split and seed: the real fresh programs are first generated by the frozen run."""
    monkeypatch.setitem(tasks.SPLIT_SEEDS, "test_fresh_b", 999002)
    monkeypatch.setattr(sc, "SPLIT", "test_fresh_b")


def test_the_second_fresh_seed_is_registered_and_new():
    seeds = {name: tasks.SPLIT_SEEDS[name] for name in (*SPLIT_ORDER, "fresh_2026_10")}
    assert tasks.SPLIT_SEEDS["fresh_2026_10b"] == 207001 and 207001 not in seeds.values()


def _previous(plan, monkeypatch):
    """A stand-in for Phase Nine's fresh split, built with another test seed."""
    monkeypatch.setitem(tasks.SPLIT_SEEDS, "test_previous", 999003)
    excluded = {tasks.canonical(p) for name in SPLIT_ORDER for g in plan.groups[name] for p in (g.source, g.counterfactual)}
    return tasks.generate_groups("test_previous", 3, excluded_programs=excluded)


def test_fresh_groups_exclude_phase_two_and_the_previous_fresh_split(monkeypatch, test_split):
    plan = _tiny_plan()
    previous, stats = _previous(plan, monkeypatch)
    monkeypatch.setattr(sc, "PLAN_HASH", plan.plan_hash)
    monkeypatch.setattr(sc, "PREVIOUS_FRESH_INVENTORY", stats["inventory_sha256"])
    monkeypatch.setattr(sc, "previous_fresh_groups", lambda p: (previous, stats))
    groups, new_stats = sc.fresh_groups(plan, count=5)
    old = {tasks.canonical(p) for name in SPLIT_ORDER for g in plan.groups[name] for p in (g.source, g.counterfactual)}
    old |= {tasks.canonical(p) for g in previous for p in (g.source, g.counterfactual)}
    new = {tasks.canonical(p) for g in groups for p in (g.source, g.counterfactual)}
    assert len(groups) == 5 and not new & old and new_stats["inventory_sha256"]


def test_a_changed_previous_split_is_refused(monkeypatch, test_split):
    plan = _tiny_plan()
    previous, stats = _previous(plan, monkeypatch)
    monkeypatch.setattr(sc, "PLAN_HASH", plan.plan_hash)
    monkeypatch.setattr(sc, "previous_fresh_groups", lambda p: (previous, stats))
    with pytest.raises(ValueError, match="recorded inventory"):
        sc.fresh_groups(plan, count=2)


def _cond(correct, old):
    return {"correct": correct, "logprob": -1.0, "superseded_correct": old, "preference": 1.0 if old else -3.0}


def _fake_run(tmp_path, family, same_breaks, other_breaks, groups=120, inventory="inv"):
    run = tmp_path / family
    run.mkdir()
    stimuli, results = [], []
    for g in range(groups):
        for k in range(3):
            sid = f"fresh_2026_10b-{g:04d}-{'AB'[k % 2]}-{'xy'[k // 2]}-{k}"
            stimuli.append({"id": sid, "group_id": f"fresh_2026_10b-{g:04d}"})
            same_bad, other_bad = same_breaks(g, k), other_breaks(g, k)
            results.append({"id": sid, "baseline": _cond(True, False),
                            "same_variable": _cond(not same_bad, same_bad), "other_variable": _cond(not other_bad, other_bad)})
    (run / "stimuli.json").write_text(json.dumps(stimuli))
    (run / "results.jsonl").write_text("".join(json.dumps(r) + "\n" for r in results))
    (run / "manifest.json").write_text(json.dumps({"family": family, "prompts": len(results), "plan_hash": sc.PLAN_HASH,
                                                   "protocol_sha256": sc.sha256_file(sc.PROTOCOL),
                                                   "stimuli_sha256": sc.sha256_file(run / "stimuli.json"),
                                                   "generation": {"inventory_sha256": inventory}}))
    (run / "completion.json").write_text(json.dumps({"status": "COMPLETE"}))
    return run


def test_verdicts_follow_the_frozen_rules(tmp_path, monkeypatch):
    monkeypatch.setattr(sc, "RESAMPLES", 2000)
    gemma = _fake_run(tmp_path, "gemma3-12b", lambda g, k: k < 2, lambda g, k: k == 0)
    qwen = _fake_run(tmp_path, "qwen2.5-7b", lambda g, k: k == 0, lambda g, k: False)
    result = sc.evaluate([gemma, qwen])
    status = {h["id"]: h["status"] for h in result["hypotheses"]}
    assert status == {"G1": "SUPPORTED", "G2": "SUPPORTED", "G3": "SUPPORTED",
                      "Q1": "SUPPORTED", "Q2": "NOT_SUPPORTED", "Q3": "SUPPORTED"}
    by_id = {h["id"]: h for h in result["hypotheses"]}
    assert by_id["G1"]["mean"] == pytest.approx(2 / 3) and by_id["G3"]["mean"] == pytest.approx(2 / 3)
    assert result["families"]["gemma3-12b"]["same_variable"]["superseded_share_of_wrong"] == 1.0


def test_families_must_share_the_same_fresh_programs(tmp_path):
    a = _fake_run(tmp_path, "gemma3-12b", lambda g, k: False, lambda g, k: False, inventory="one")
    b = _fake_run(tmp_path, "qwen2.5-7b", lambda g, k: False, lambda g, k: False, inventory="two")
    with pytest.raises(ValueError, match="different fresh programs"):
        sc.evaluate([a, b])


def test_run_end_to_end_on_a_fixture_model(tmp_path, monkeypatch, model_factory, tokenizer, test_split):
    """Tiny random model and fixture tokens; plumbing only, never a real result."""
    import transformers

    from test_answer_knockout import _eager

    plan = _tiny_plan()
    previous, stats = _previous(plan, monkeypatch)
    lock = tmp_path / "model-lock-gemma3-12b.json"
    lock.write_text(json.dumps({"models": {"target": {"revision": "r", "files": {}}}}))
    monkeypatch.setattr(sc, "PLAN_HASH", plan.plan_hash)
    monkeypatch.setattr(sc, "PREVIOUS_FRESH_INVENTORY", stats["inventory_sha256"])
    monkeypatch.setattr(sc, "previous_fresh_groups", lambda p: (previous, stats))
    monkeypatch.setattr(sc, "build_plan", lambda: plan)
    monkeypatch.setattr(sc, "GROUPS", 4)
    monkeypatch.setattr(sc, "fresh_groups", lambda p, count=4, real=sc.fresh_groups: real(p, count))
    monkeypatch.setattr(sc, "supersession_row", lambda item, split, tok: {
        "id": item["id"], "group_id": item["group_id"], "kind": "literal", "answer": "7", "superseded": "4",
        "queries": [1], "keys": {"same_variable": [0], "other_variable": [0]},
        "sequence": {"ids": item["input_ids"] + [17], "positions": [len(item["input_ids"]) - 1], "targets": [17]},
        "superseded_sequence": {"ids": item["input_ids"] + [14], "positions": [len(item["input_ids"]) - 1], "targets": [14]}})
    monkeypatch.setattr(sc, "load_model", lambda path, role, device: _eager(model_factory(layers=3)))
    monkeypatch.setattr(sc, "read_lock", lambda path: json.loads(path.read_text()))
    monkeypatch.setattr(sc, "model_paths", lambda lock, cache: {"target": tmp_path})
    monkeypatch.setattr(sc, "verify_models", lambda lock, paths: {})
    monkeypatch.setattr(sc, "compatibility", lambda device: {})
    monkeypatch.setattr(transformers.AutoTokenizer, "from_pretrained", lambda path, **kwargs: tokenizer)
    run_dir = tmp_path / "confirm"
    sc.main(["run", "--lock", str(lock), "--device", "cpu", "--run-dir", str(run_dir)])
    completion = json.loads((run_dir / "completion.json").read_text())
    manifest = json.loads((run_dir / "manifest.json").read_text())
    assert completion["status"] == "COMPLETE" and completion["rows_written"] == manifest["prompts"] == 16
    assert manifest["split"] == "test_fresh_b"
